// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        // make actor the owner first (works for reference and mutant alike)
        vm.prank(address(this));
        c.setOwner(actor);
        // actor (now owner) sets a new, nonzero owner
        vm.prank(actor);
        c.setOwner(newOwner);
        // General rule: owner equals the address passed to setOwner.
        assertTrue(c.owner() == newOwner);
    }
}
